  "quiz": [
    {
      "id": "q1",
      "q": "十五年前江南盐案里被问斩的巡盐御史，姓什么？",
      "options": [
        {
          "key": "A",
          "text": "冯"
        },
        {
          "key": "B",
          "text": "何"
        },
        {
          "key": "C",
          "text": "欧"
        },
        {
          "key": "D",
          "text": "吴"
        }
      ],
      "answer": "C",
      "clue": "dy_zhang_3",
      "explain": "张明察书里夹着的复核文书抄件写得明白：江南巡盐御史欧明远，私吞盐课八十万两，拟斩。"
    },
    {
      "id": "q2",
      "q": "欧弦月少年时在哪里讨生活？",
      "options": [
        {
          "key": "A",
          "text": "扬州的影戏班"
        },
        {
          "key": "B",
          "text": "苏州的绣坊"
        },
        {
          "key": "C",
          "text": "京城的教坊司"
        },
        {
          "key": "D",
          "text": "秦淮河的画舫"
        }
      ],
      "answer": "A",
      "clue": "dy_ou_4",
      "explain": "琴囊夹层里那片驴皮影人背面墨书「扬州鬼家班」，旁边抄着挑影人的口诀。"
    },
    {
      "id": "q3",
      "q": "蓉锦书和欧弦月是什么关系？",
      "options": [
        {
          "key": "A",
          "text": "失散多年的亲姐妹"
        },
        {
          "key": "B",
          "text": "素不相识"
        },
        {
          "key": "C",
          "text": "曾是主仆"
        },
        {
          "key": "D",
          "text": "少时在同一个戏班"
        }
      ],
      "answer": "D",
      "clue": "dy_rong_4",
      "explain": "蓉锦书衣箱底的鬼家班旧戏单上，「锦书」「弦儿」两个小名挨在一起。"
    },
    {
      "id": "q4",
      "q": "刘听澜三年前会试得中，背后藏着什么事？",
      "options": [
        {
          "key": "A",
          "text": "冒名顶替了别人"
        },
        {
          "key": "B",
          "text": "考前从甄府送来的食盒里得了考题"
        },
        {
          "key": "C",
          "text": "家里花钱买了功名"
        },
        {
          "key": "D",
          "text": "抄了别人的旧文章"
        }
      ],
      "answer": "B",
      "clue": "dy_liu_4",
      "explain": "刘听澜箱底那张折了四折的纸条写着会试三场的题目，背面印着食盒的油渍。"
    },
    {
      "id": "q5",
      "q": "吴回春进甄府当医女，背后是谁的安排？",
      "options": [
        {
          "key": "A",
          "text": "甄怀璋亲自请来"
        },
        {
          "key": "B",
          "text": "三皇子府"
        },
        {
          "key": "C",
          "text": "太子府詹事何守拙"
        },
        {
          "key": "D",
          "text": "大理寺"
        }
      ],
      "answer": "C",
      "clue": "dy_he_4",
      "explain": "何守拙书箱底的小册每月十五记一笔「吴氏，报甄公脉案」，两年没断。"
    },
    {
      "id": "q6",
      "q": "魏如海这两年暗中把甄府的消息卖给了谁？",
      "options": [
        {
          "key": "A",
          "text": "三皇子府长史撒谋远"
        },
        {
          "key": "B",
          "text": "太子府詹事何守拙"
        },
        {
          "key": "C",
          "text": "大理寺少卿张明察"
        },
        {
          "key": "D",
          "text": "内阁的同僚"
        }
      ],
      "answer": "A",
      "clue": "dy_sa_3",
      "explain": "撒谋远随身的小账本里记着十几笔「魏，若干两」，与魏如海床席下的泰丰号银票对得上。"
    },
    {
      "id": "q7",
      "q": "甄怀璋锁在密匣里的那道奏折，请旨复查的是哪一桩旧案？",
      "options": [
        {
          "key": "A",
          "text": "会试泄题案"
        },
        {
          "key": "B",
          "text": "宣府军饷案"
        },
        {
          "key": "C",
          "text": "东宫失窃案"
        },
        {
          "key": "D",
          "text": "江南盐案"
        }
      ],
      "answer": "D",
      "clue": "dy_sa_4",
      "explain": "撒谋远被褥夹层里那道奏折的封面写着「请复查江南盐案事」。"
    }
  ],
